CREATE OR REPLACE FUNCTION app_private.reporting_team_options(_org_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE managed boolean; BEGIN
 IF NOT(public.user_belongs_to_org(auth.uid(),_org_id) OR public.has_role(auth.uid(),'admin')) OR app_private.user_is_donor_for_org(auth.uid(),_org_id) THEN RAISE EXCEPTION 'Organisation access required'; END IF;
 managed:=public.can_manage_reporting(_org_id) AND NOT public.user_is_field_scoped(auth.uid(),_org_id);
 RETURN jsonb_build_object('programs',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'name',name)),'[]') FROM programs WHERE organization_id=_org_id AND deleted_at IS NULL AND (managed OR id IN(SELECT public.user_assigned_program_ids(auth.uid(),_org_id)))),'projects',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'name',name,'program_id',program_id)),'[]') FROM projects WHERE organization_id=_org_id AND deleted_at IS NULL AND (managed OR id IN(SELECT public.user_assigned_project_ids(auth.uid(),_org_id)) OR (public.user_is_program_scoped(auth.uid(),_org_id) AND program_id IN(SELECT public.user_assigned_program_ids(auth.uid(),_org_id))))),'staff',CASE WHEN managed THEN (SELECT COALESCE(jsonb_agg(jsonb_build_object('user_id',om.user_id,'name',COALESCE(p.full_name,'Staff member'),'program_ids',(SELECT COALESCE(jsonb_agg(x),'[]') FROM public.user_assigned_program_ids(om.user_id,_org_id)x),'project_ids',(SELECT COALESCE(jsonb_agg(x),'[]') FROM public.user_assigned_project_ids(om.user_id,_org_id)x))),'[]') FROM organization_members om LEFT JOIN profiles p ON p.user_id=om.user_id WHERE om.organization_id=_org_id) ELSE '[]'::jsonb END,'forms',CASE WHEN managed THEN (SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'name',name,'program_id',program_id,'project_id',project_id)),'[]') FROM me_forms WHERE organization_id=_org_id AND deleted_at IS NULL) ELSE '[]'::jsonb END); END $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef(p.oid) INTO d FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='app_private' AND p.proname='guard_reporting_obligation'; d:=replace(d,$q$IF (NEW.scope_type='program'$q$,$q$IF NEW.is_active AND NEW.deleted_at IS NULL AND ((NEW.scope_type='program'$q$); d:=replace(d,$q$NEW.organization_id))) THEN RAISE EXCEPTION 'Staff must be on the selected team'$q$,$q$NEW.organization_id)))) THEN RAISE EXCEPTION 'Staff must be on the selected team'$q$); EXECUTE d; END $$;
NOTIFY pgrst, 'reload schema';